import bpy, subprocess, os, re
expected=r'C:\mcp-blender\salvador_lacerda_do_zero.blend'
repo=r'C:\mcp-blender\vendor\projeto-salvador-elevador-lacerda'
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=os.path.normcase(os.path.normpath(expected)):
    raise RuntimeError('arquivo Blender errado')
try:
    subprocess.run(['git','-C',repo,'fetch','origin','chatgpt/blender-collab'],check=True,capture_output=True,text=True)
    def run_script(path):
        cp=subprocess.run(['git','-C',repo,'show','FETCH_HEAD:'+path],check=True,capture_output=True,text=True,encoding='utf-8')
        exec(compile(cp.stdout,path,'exec'),{'__name__':'__main__','__file__':os.path.join(repo,path)})
    run_script('scripts/blockout_nucleo_vertical_v1.py')
    c=bpy.data.collections.get('E | NUCLEO VERTICAL 4 ELEVADORES | blockout v1')
    if not c: raise RuntimeError('nucleo nao criado')
    groups={}
    for o in list(c.objects):
        base=re.sub(r'\.\d{3}$','',o.name)
        groups.setdefault(base,[]).append(o)
    for base,objs in groups.items():
        if len(objs)>1:
            objs=sorted(objs,key=lambda x:x.name)
            for i,o in enumerate(objs,1): o.name=f'{base} | {i}'
    run_script('scripts/qa_elevador_interior.py')
    run_script('scripts/qa_world_blockout.py')
    bpy.ops.wm.save_as_mainfile(filepath=expected)
    print('BATCH_0081_VERTICAL_CORE_PASS_AND_SAVED')
except Exception as e:
    print('BATCH_0081_FAIL_ROLLBACK',repr(e))
    try: bpy.ops.wm.open_mainfile(filepath=expected)
    except Exception as r: print('ROLLBACK_OPEN_FAIL',repr(r))
    raise
